#pragma material(ShadingModel = Unlit, Backend = Graph)

/// @group Look
/// @static
uniform bool UseWarm = true;

export void M_RtStaticSwitch(inout material m)
{
    float3 Colour = float3(0.0, 0.5, 1.0);
    float3 Colour_2 = float3(1.0, 0.5, 0.0);

    m.EmissiveColor = UseWarm ? Colour_2 : Colour;
}

#pragma layout(Node, Var = UseWarm, X = 0, Y = -256)
#pragma layout(Node, Var = Colour, X = 148, Y = -620)
#pragma layout(Node, Var = Colour_2, X = 148, Y = -80)
